"use client"

import animation from "react-useanimations/lib/messageCircle"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "Message Circle" from https://useanimations.com (MIT): https://useanimations.com/icons/message-circle
export function AnimatedMessageCircle(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="hover-replay"
      {...props}
    />
  )
}
